// ultimos 30 dias (o mesmo periodo que o IPMA devolve) na regiao Portugal/Acores/Iberia
const inicio = new Date(Date.now() - 30 * 24 * 3600 * 1000).toISOString().slice(0, 10);
msg.url = 'https://www.seismicportal.eu/fdsnws/event/1/query'
    + '?format=json&orderby=time&limit=3000'
    + '&minlatitude=29&maxlatitude=45&minlongitude=-32&maxlongitude=-5'
    + '&starttime=' + inicio;
return msg;

const feats = (msg.payload && msg.payload.features) || [];
if (!feats.length) {
    node.warn('EMSC: sem eventos');
    return null;
}
const ids = [];
const payloads = [];
for (const f of feats) {
    const id = f.id || (f.properties && f.properties.unid);
    if (!id) continue;
    ids.push(id);
    payloads.push(JSON.stringify(f));
}
msg.rotulo = 'EMSC';
msg.n = ids.length;
msg.query = `INSERT INTO raw_sismos (fonte, formato, id_externo, payload)
             SELECT 'EMSC', 'geojson', t.id, t.p
             FROM UNNEST($1::text[], $2::text[]) AS t(id, p)
             ON CONFLICT (fonte, id_externo) DO NOTHING`;
msg.params = [ids, payloads];
return msg;
